/*
 * prog49_bst – binary‑search‑tree utility
 *
 * Behaviour (as observed from the original binary):
 *
 *   prog49_bst <mode> <num1> <num2> ...
 *
 *   <mode> must be one of:  "in"   – inorder traversal
 *                           "pre"  – preorder traversal
 *                           "post" – postorder traversal
 *
 *   All remaining arguments are interpreted as signed decimal integers
 *   (base 10) and are inserted into a binary search tree.  The tree is
 *   stored in three parallel static arrays (value, left, right) with a
 *   maximum capacity of 64 nodes – this matches the limits used by the
 *   original program.
 *
 *   After all numbers have been inserted the requested traversal is
 *   performed.  The values are printed as decimal numbers separated by a
 *   single space; no space is printed before the first value.  A newline
 *   is printed after the traversal.  If the tree is empty the program
 *   prints the word "EMPTY" (followed by a newline) instead of a traversal.
 *
 *   Invalid command line usage (wrong number of arguments or an unknown
 *   mode) results in the message "INVALID_MODE" (followed by a newline)
 *   and the program exits with status 0.
 *
 *   The implementation below reproduces the observable behaviour of the
 *   original binary while being clear and idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64          /* matches the original limit (0x3f) */
#define NIL       -1          /* sentinel for empty child / empty tree */

/* ------------------------------------------------------------------ */
/* Global data structures – exactly as the original binary used them. */
static long value[MAX_NODES];
static int  left[MAX_NODES];
static int  right[MAX_NODES];

static int root = NIL;        /* index of the root node, -1 == empty */
static int used = 0;          /* number of nodes currently stored   */
static int printed = 0;       /* flag used by the traversal printers */

/* ------------------------------------------------------------------ */
/* Insert a value into the BST.  The algorithm follows the logic that
 * the original program implemented (including the special handling of
 * the very first node). */
static void bst_insert(long x)
{
    int idx, cur, parent;

    /* First node – just allocate it and make it the root. */
    if (root == NIL) {
        if (used >= MAX_NODES) return;          /* safety – original silently stopped */
        idx = used++;
        value[idx] = x;
        left[idx] = right[idx] = NIL;
        root = idx;
        return;
    }

    /* Walk the tree to find the insertion point. */
    cur = root;
    parent = NIL;
    while (cur != NIL) {
        if (x == value[cur]) {
            /* The original program ignored duplicate values – we do the same. */
            return;
        }
        parent = cur;
        if (x < value[cur])
            cur = left[cur];
        else
            cur = right[cur];
    }

    /* Allocate a new node. */
    if (used >= MAX_NODES) return;              /* safety */
    idx = used++;
    value[idx] = x;
    left[idx] = right[idx] = NIL;

    /* Attach it to its parent. */
    if (x < value[parent])
        left[parent] = idx;
    else
        right[parent] = idx;
}

/* ------------------------------------------------------------------ */
/* Traversal helpers – they all share the same printing logic. */
static void print_node(long v)
{
    if (printed)
        putchar(' ');
    printf("%ld", v);
    printed = 1;
}

static void inorder(int node)
{
    if (node == NIL) return;
    inorder(left[node]);
    print_node(value[node]);
    inorder(right[node]);
}

static void preorder(int node)
{
    if (node == NIL) return;
    print_node(value[node]);
    preorder(left[node]);
    preorder(right[node]);
}

static void postorder(int node)
{
    if (node == NIL) return;
    postorder(left[node]);
    postorder(right[node]);
    print_node(value[node]);
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    const char *mode;
    int i;

    /* ----------------------------------------------------------------
     * Argument validation – exactly the same decisions as the original.
     * ---------------------------------------------------------------- */
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }

    mode = argv[1];
    if (strcmp(mode, "in") && strcmp(mode, "pre") && strcmp(mode, "post")) {
        puts("INVALID_MODE");
        return 0;
    }

    /* ----------------------------------------------------------------
     * Insert all numeric arguments.
     * ---------------------------------------------------------------- */
    for (i = 2; i < argc; ++i) {
        char *endptr;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr;               /* original ignored conversion errors */
        bst_insert(v);
    }

    /* ----------------------------------------------------------------
     * Perform the requested traversal (or report an empty tree).
     * ---------------------------------------------------------------- */
    if (root == NIL) {
        puts("EMPTY");
    } else {
        printed = 0;               /* reset the spacing flag */
        if (!strcmp(mode, "in"))
            inorder(root);
        else if (!strcmp(mode, "pre"))
            preorder(root);
        else                        /* mode == "post" */
            postorder(root);
        putchar('\n');
    }

    return 0;
}
